  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => '我们已收到您的收据,谢谢您 🌱 我们会尽快回复您有关付款的信息。',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => '我们已收到您的收据,谢谢您🌱您的捐款已确认。',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => '我们已经收到此收据,谢谢您🌱我们会尽快回复您有关付款的信息。',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => '该收据似乎之前已上传到我们的系统。同一张收据不能用于第二次捐赠。如果您进行了不同的付款,请发送收据;我们的团队也会检查。',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => '我们收到了您的收据。上面的金额 (%1$s) 似乎与您的捐款金额 (%2$s) 不符。你能检查一下吗?如果您进行了不同的付款,您可以写在这里;我们的团队也会看一看。',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => '我们已收到您的收据,但收据上的收件人似乎不是我们协会。捐款仅以“%s”名义存入我们的帐户。你能检查一下吗?我们的团队也会看一下。',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => '我们已收到您的收据,但收据上的收件人似乎与我们的帐户不符。你能检查一下吗?我们的团队也会看一下。',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => '您发送的文件看起来不像付款收据。如果您已付款,您可以在此处发送收据或付款屏幕的屏幕截图。',
