  'Connection not found. Save the settings first.' => '未找到连接。先保存设置。',
  'The message was only image code; it was not sent.' => '该消息只是图像代码;它没有被发送。',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => '该联系人已被列入黑名单;没有发送任何消息。将它们从阻止列表中删除以重新写入。',
  'Message could not be saved.' => '无法保存消息。',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => '此联系人通过隐藏的 WhatsApp 号码 (@lid) 进行写入,Evolution API(版本%s)无法发送到此地址。将Evolution API服务器更新到2.3或更高版本;如果联系人的真实号码到达,插件就会发送到那里。',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => '此联系人通过隐藏的 WhatsApp 号码 (@lid) 进行写入,Evolution API 无法发送到此地址。将Evolution API服务器更新到2.3或更高版本;如果联系人的真实号码到达,插件就会发送到那里。',
  'No WhatsApp connection.' => '没有 WhatsApp 连接。',
  'Connected ✓' => '已连接 ✓',
  'Not connected (state: %s). Connect with QR.' => '未连接(状态:%s)。通过二维码连接。',
  'Webhook points to this site ✓' => 'Webhook 指向此站点 ✓',
  'Evolution API version: %s' => 'Evolution API 版本:%s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(旧:回复隐藏号码(@lid)联系人可能会失败,更新至2.3或更高版本)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Webhook 未指向此站点。按“设置网络钩子”。',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Webhook 设置 ✓ 传入消息现在将到达此处。',
  'Importing recent chats, this may take a while…' => '导入最近的聊天记录,这可能需要一段时间......',
  'Messages stored in Evolution: %s' => 'Evolution 中存储的消息:%s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution 不存储消息,因此无法加载较旧的消息。在 Evolution 服务器上,将 DATABASE_SAVE_DATA_NEW_MESSAGE 和 DATABASE_SAVE_DATA_HISTORIC 设置为 true;对于较旧的对话,当您使用 QR 重新连接线路时,请在实例设置中保持“同步完整历史记录”处于打开状态。',
  '%1$s chats, %2$s messages imported ✓' => '%1$s聊天、导入%2$s消息 ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => '通过 WhatsApp 扫描此代码 › 链接的设备 › 链接设备。',
  'Pairing code:' => '配对代码:',
  'This line is already connected ✓' => '该线路已连接 ✓',
  'Save the settings first.' => '先保存设置。',
  'Error:' => '错误:',
  'Delete this connection? Chat history is kept.' => '删除这个连接吗?聊天记录被保留。',
  'Asking the AI…' => '询问人工智能...',
  'Working ✓ (%2$s ms): %1$s' => '工作 ✓(%2$s毫秒):%1$s',
  'Save the key and model first.' => '首先保存密钥和模型。',
  'Connections' => '连接',
  'Auto replies' => '自动回复',
  'AI and assistant' => 'AI与助手',
  'System check' => '系统检查',
  'Connect your WhatsApp line, manage auto replies and labels.' => '连接您的 WhatsApp 线路,管理自动回复和标签。',
  'Open chats' => '打开聊天室',
  'Settings saved.' => '设置已保存。',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => '呼叫中心所需的连接和设置。显示保存状态;使用每个选项卡上的“测试”按钮进行实时检查。主题的系统检查屏幕上的其他插件也会出现相同的检查。',
  'WhatsApp lines' => 'WhatsApp 线路',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => '消息通过 Evolution API 发送和接收。 WhatsApp 连接在 Flux Mail 中管理;在这里选择使用哪一个。 URL 和 API 密钥保留在那里,因此当它们发生更改时,您无需在此处更新它们。',
  'Communication › Connections' => '通讯 › 连接',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => '消息通过 Evolution API 发送和接收。如果在 Flux 证书中设置了 Evolution 提供程序,您可以选择相同的连接; URL 和 API 密钥保留在那里。',
  'Add line' => '添加行',
  'Setup steps' => '设置步骤',
  'Add the line and save.' => '添加该行并保存。',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => '使用“测试连接”来查看 Evolution 是否可达。如果线路未链接,请选择“使用 QR 连接”并从手机扫描。',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => '按“设置网络钩子”。传入的消息以及从手机和 Flux 证书发送的消息都会实时显示在此处。',
  'Optionally bring in past messages with "Import recent chats".' => '可以选择通过“导入最近的聊天记录”引入过去的消息。',
  'connected' => '已连接',
  'connecting' => '连接',
  'not connected' => '未连接',
  'not on server' => '不在服务器上',
  'unreachable' => '无法到达的',
  'Flux Mail connection: %s' => 'Flux 邮件连接:%s',
  'Flux Mail connection #%d (not found or disabled)' => 'Flux 邮件连接 #%d(未找到或已禁用)',
  'Use Flux Certificates provider: %s' => '使用 Flux 证书提供商:%s',
  'Enter separate Evolution API details' => '输入单独的 Evolution API 详细信息',
  'Line name (e.g. Main line)' => '线路名称(例如主线)',
  'Connection details' => '连接详情',
  'API URL' => 'API网址',
  'Instance name' => '实例名称',
  'API key (apikey)' => 'API 密钥 (apikey)',
  '•••••••• (saved; type to change)' => '•••••••(已保存;键入进行更改)',
  'Webhook URL' => '网络钩子 URL',
  'Regenerate secret key' => '重新生成密钥',
  'Last webhook: %s' => '最后一个 Webhook:%s',
  'No webhook received yet.' => '尚未收到网络钩子。',
  'Test connection' => '测试连接',
  'Connect with QR' => '通过二维码连接',
  'QR, status and accounts: Communication › Connections' => '二维码、状态和帐户:通讯 › 连接',
  'Set up webhook' => '设置网络钩子',
  'Import recent chats' => '导入最近的聊天记录',
  'The webhook URL and test buttons appear after saving.' => '保存后将出现 webhook URL 和测试按钮。',
  'Appearance' => '外观',
  'Panel title' => '面板标题',
  'Site name if empty. The {brand} variable uses this too.' => '站点名称(如果为空)。{brand}变量也使用它。',
  'Accent color' => '强调色',
  'Behavior' => '行为',
  'Send read receipts (blue ticks) when a chat is opened' => '打开聊天时发送已读回执(蓝色勾号)',
  'Prefix messages with the agent\'s name (*Name:*)' => '在消息中添加代理姓名前缀 (*Name:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => '客服人员只能看到分配给他们的聊天和未分配的聊天(管理员查看全部)',
  'Also show WhatsApp group messages' => '还显示 WhatsApp 群组消息',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => '新界面(实验性):聊天页面打开时与桌面和移动应用程序在同一屏幕上',
  'Live update interval (sec)' => '实时更新间隔(秒)',
  'Agents' => '代理商',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => '授予用户%s角色;他们只能看到聊天屏幕,无法打开设置。管理员始终具有访问权限。',
  'Add new user' => '添加新用户',
  'Data' => '数据',
  'Also delete all chats, messages and media files when the plugin is deleted' => '删除插件时也会删除所有聊天、消息和媒体文件',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => '媒体文件保存在 wp-content/uploads/flx-chat 中,禁止外部访问。当网站迁移时,它们会随着上传内容一起移动。',
  'Mon' => '周一',
  'Tue' => '星期二',
  'Wed' => '周三',
  'Thu' => '星期四',
  'Fri' => '周五',
  'Sat' => '星期六',
  'Sun' => '太阳',
  'Welcome message' => '欢迎留言',
  'Send automatically to people who write to us for the first time' => '自动发送给第一次给我们写信的人',
  'Away message' => '离开消息',
  'Auto reply to messages received outside business hours' => '自动回复工作时间以外收到的消息',
  'Business days' => '工作日',
  'Start' => '开始',
  'End' => '结束',
  'At most once per contact every (hours)' => '每次联系最多(小时)一次',
  'Timezone: %1$s. Now: %2$s.' => '时区:%1$s。现在:%2$s。',
  'within business hours' => '营业时间内',
  'outside business hours' => '营业时间外',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => '{first_name}、{name}、{brand}、{site}、{date}变量可以在文本中使用。',
  'Chat labels' => '聊天标签',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => '标记聊天并过滤列表(例如捐赠、投诉、跟进)。',
  'Add label' => '添加标签',
  'Label name' => '标签名称',
  'Creating records from chats' => '从聊天中创建记录',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => '聊天标题中的按钮创建捐赠记录(Flux Donate)和证书(Flux Certificates),并且传入收据与记录匹配。如果未安装插件,其按钮将被隐藏。',
  'Agents can create donation records and match receipts' => '代理人可以创建捐赠记录并匹配收据',
  'Agents can create and send certificates' => '代理可以创建和发送证书',
  'Show quick reply bubbles above the message box' => '在消息框上方显示快速回复气泡',
  'Donation messages' => '捐款留言',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => '创建记录时发送给该人员的就绪文本(发送前可编辑)。如果留空,则使用默认文本。',
  'Awaiting payment (promised transfer)' => '等待付款(承诺转账)',
  'Donation received' => '收到捐款',
  'Receipt confirmed' => '已确认收货',
  'Bank details ({bank})' => '银行详细信息 ({bank})',
  'Recipient name, bank, IBAN' => '收款人姓名、银行、IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => '如果为空,则使用 WooCommerce › 付款 › 银行转帐中的帐户。',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => '变量:{first_name}、{name}、{donation}、{amount}、{quantity}、{bank}、{certificate_link}、{agent}、{brand}、{date}。',
  'AI connection' => '人工智能连接',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => '密钥、提示缓存、支出限制和使用日志来自 Flux AI & MCP 插件;呼叫中心的所有人工智能请求都经过它。型号选择留在这里;如果字段为空,则使用 Flux AI 中为此插件选择的模型(或默认模型)。',
  'Open Flux AI settings' => '打开 Flux AI 设置',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'AI 需要 Flux AI & MCP 插件。安装并激活它,然后在 Flux AI & MCP › 设置中输入 OpenRouter 和/或 Anthropic 密钥。在此之前,建议、助手、收据阅读、语音消息和摘要都将关闭。',
  'Creativity (0–1)' => '创造力 (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => '较低的值提供更一致的答复,较高的值提供更自由的答复。推荐0.4。',
  'Model (for suggestions)' => '型号(供建议)',
  'Assistant model (optional)' => '助理模型(可选)',
  'Model above' => '以上型号',
  'Only models that support tools are listed.' => '仅列出支持工具的型号。',
  'Receipt reading model (optional)' => '收据读取模型(可选)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => '如果所选模型无法读取图像,则会自动使用廉价的视觉模型。',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => '本月 (%1$s):%2$s请求、%3$s代币,约 $%4$s。',
  'Reply suggestions' => '回复建议',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => '在消息框上方,从对话中建议下一条消息。代理单击“发送”或将其放入“编辑”框中。建议永远不会单独发送。',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => '当该人发送最后一条消息时,自动准备建议(如果关闭,请使用 ✨ 按钮询问)',
  'Organization info and tone' => '组织信息和基调',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => '例如我们协会在伊斯坦布尔种植树苗。每年 11 月至 3 月期间进行种植。捐赠后,证书将通过 WhatsApp 发送。使用温暖但正式的语气。',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => '建议和助手用这个。捐赠类型、价格、银行详细信息和快速回复都会自动添加。',
  'Suggestion provider' => '建议提供者',
  'Donation assistant (automatic replies)' => '捐款助手(自动回复)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => '启用后,助手会自行回复:它会打招呼,询问姓名,发送捐赠选项和价格,可选择收集电子邮件和“以谁的名义”,并在每次更改后要求确认。确认后,它会在 Flux Donate 中打开“等待付款”记录,并将捐赠链接、收件人、IBAN 和参考信息作为单独的消息发送。如果该主题留下捐款,则会将聊天交给团队。',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Flux Donate 插件未激活;助理无法创建捐赠记录。',
  'Instructions, documents, AI chats and test chat' => '说明、文档、AI 聊天和测试聊天',
  'Turn on the donation assistant (untick to turn it off everywhere)' => '打开捐赠助手(取消勾选即可在所有地方将其关闭)',
  'Which chats should it reply to' => '它应该回复哪些聊天',
  'In all chats (recommended)' => '在所有聊天中(推荐)',
  'In chats not assigned to an agent' => '在未分配给客服人员的聊天中',
  'Only outside working hours' => '仅限工作时间以外',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => '当客服人员在聊天中(通过面板或电话)进行书写时,助理会在下面的时间内保持安静。使用聊天标题中的助手按钮在每次聊天时打开或关闭它。',
  'Test mode: reply only to the numbers below' => '测试模式:仅回复以下号码',
  'Test numbers' => '测试号码',
  'Separate with commas or new lines. Not used when test mode is off.' => '用逗号或换行符分隔。测试模式关闭时不使用。',
  'Quiet after an agent writes (hours)' => '代理写信后安静(小时)',
  'Quantities in the price list' => '价格表中的数量',
  'Conversation history (hours)' => '对话历史记录(小时)',
  'Before replying, the assistant reads all messages from this period.' => '在回复之前,助理会阅读该时段的所有消息。',
  'Donation types the assistant offers' => '助理提供的捐赠类型',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => '如果未选择任何类型,则提供所有开放类型。当在 Flux Donate 中打开新类型时,助手也会知道。',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => '收据预检查:当联系人发送收据时,AI 将金额、收件人和 IBAN 与捐赠进行比较,告诉联系人结果,将文件附加到捐赠记录中,并将聊天交给团队进行最终批准(不标记为已付款)',
  'Last line of the price list' => '价格表的最后一行',
  'Payment details' => '付款详情',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => '如果收件人和 IBAN 为空,则使用 WooCommerce › 付款 › 银行转帐中的内容(订单上显示的帐户)。仅当助理应使用不同的帐户时才填写它们。',
  'Recipient name' => '收件人姓名',
  'Transfer description' => '转账说明',
  'Variables: {type}, {name}, {amount}, {quantity}' => '变量:{type}、{name}、{amount}、{quantity}',
  'Donation page URL' => '捐款页面网址',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => '所选类型和数量将添加到链接 (?flxb_opt=...&flxb_qty=...)。',
  'Message after the payment details' => '付款详情后留言',
  'Donation cancellation question' => '取消捐赠问题',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => '助理仅会在经本人确认后取消未付款的捐款。空=默认文本。变量:{bagis}、{tutar}。',
  'Message sent when the daily limit is reached' => '达到每日限额时发送的消息',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => '当聊天达到当日回复上限时发送一次;聊天将交给团队。从聊天的 ⋮ 菜单重置它 › 助理使用。',
  'Message sent when handing over to the team' => '移交团队时发送的消息',
  'Message sent when the assistant cannot answer' => '助理无法接听时发送的消息',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => '如果AI失败、达到时间限制或队列太长,则会发送此消息并将聊天交给团队;这个人永远不会没有答案。',
  'Minimum wait before the holding message (s)' => '保留消息之前的最短等待时间',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => '直到该人的消息发送后这么多秒才会发送保留消息;与此同时,助理重试。',
  'Longest time for one answer (s)' => '一次回答的最长时间(秒)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger 可以在约 60 秒内削减请求;建议50。',
  'Numbers notified on handoff' => '交接时通知的号码',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => '当助理将聊天交给团队时,一条 WhatsApp 消息将从同一行发送到这些号码:联系人的姓名、电话、原因、最后一条消息和面板链接。用逗号或换行符分隔。助理不会与这些号码交谈。',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => '当联系人写下其中之一时,助理会立即发送上面的移交消息,并在该聊天中关闭。如果留空,则使用示例列表。',
  'Extra instructions for the assistant' => '给助理的额外说明',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => '例如科贾埃利种植了树苗。捐赠确认后将发送证书。',
  'Last message when a contact opts out' => '联系人选择退出时的最后一条消息',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => '如果有人写了“不要给我发消息”之类的内容,助手会发送此消息并将其列入黑名单。被列入黑名单的人无法收到 WhatsApp、电子邮件或短信;管理“聊天”下的列表 › ☰ › 阻止列表。',
  'Contact memory and background jobs' => '联系内存和后台作业',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => '联系人记忆:助手记住持久的细节(地址形式、亲属姓名、号码、偏好);过期聊天记录已汇总',
  'Summarize a chat after it has been quiet for (hours)' => '安静(几个小时)后总结一次聊天',
  'Maximum jobs at the same time' => '同时最大作业数',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => '可以同时回答多少人。助理回复始终优先;当有人正在回答或等待时,摘要不会开始。每个作业使用一名 PHP 工作人员:在共享主机上,保持在站点总工作人员限制的一半以下(例如 60 名工作人员中的 20-30 名)。',
  'Workers reserved for replies' => '保留回复的工作人员',
  'This many workers never take summaries or reminders.' => '很多工人从来不做总结或提醒。',
  'Summary hours' => '总结时间',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => '汇总仅在这些时间之间运行(手动“立即汇总”除外)。如果两者相同,则任何时间。',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => '当有人发送语音消息时,助手会将其转换为文本并回复(文本也会作为系统线路显示在面板中)',
  'Longest voice message (sec)' => '最长语音消息(秒)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => '对于较长的消息,助理会说“语音消息太长,我们无法收听”。',
  'Voice message model (optional)' => '语音留言模型(可选)',
  'Cheap audio model (Gemini Flash Lite)' => '廉价音频模型(Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => '必须是接受音频的 OpenRouter 模型(Claude 不接受)。需要 OpenRouter 密钥。',
  'Images' => '图片',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => '使用 Flux AI 图像渲染器(Flux AI 和 MCP › 设置 › 图像)。',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => '服务器上没有图像渲染器:在 Flux AI & MCP › 设置 › 图像中输入 Gotenberg 地址或安装 Imagick (SVG)。在此之前,助手不会绘制图像。',
  'Works once Flux AI 0.2.0 or later is installed.' => '安装 Flux AI 0.2.0 或更高版本后即可工作。',
  'Donation on behalf of someone' => '代表某人捐款',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => '如果捐款是以他人名义进行的,并且提供了他们的号码(联系卡或键入的号码),请在付款获得批准后将证书发送到 WhatsApp 上的该号码',
  'Message sent before the certificate' => '证书之前发送的消息',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => '然后发送来自 Flux 证书的 WhatsApp 证书消息。变量:{ad}、{bagisci}、{bagis}、{brand}。',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => '如果有人询问,助理会设置提醒(例如“每月提醒我种植树苗”、“每月向我发送您的最新项目”、“每月向我要一棵树苗”);当到期时,助理会编写并发送消息',
  'When no time is given' => '当没有给定时间时',
  'At most per person' => '每人最多',
  'Staff (Flux Roles)' => '员工(通量角色)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => '安装 Flux Roles 1.1.0 后即可使用:在个人资料 › WhatsApp 号码中设置号码的用户将根据其权限获得额外的辅助工具。',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => '经许可,为员工提供额外的辅助工具(代表有付款链接的人、我的捐赠者、一般报告)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => '当他们推荐的捐款已支付或取消时,通过 WhatsApp 通知工作人员',
  'First message to the donor for a donation opened by staff' => '工作人员向捐赠者发出的第一条捐赠信息',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => '您好{ad}🌱 我们已收到您通过{personel}发出的{bagis}捐款请求。您可以通过以下详细信息进行付款。',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => '随后是付款链接和银行详细信息。变量:{ad}、{adsoyad}、{personel}、{bagis}。',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => '当工作人员推荐的捐款支付并制作证书后,也通过 WhatsApp 将其发送给工作人员(就像捐赠者一样)',
  'Message sent to the staff member before the certificate' => '证书前发送给工作人员的消息',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => '变量:{ad}、{bagisci}、{bagis}、{no}、{brand}。',
  'How many times staff can resend a donation\'s certificate' => '工作人员可以重新发送捐赠证书多少次',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => '助理会列出收件人并在发送前要求确认。 0:关闭。',
  'Code verification for record lookups' => '记录查找的代码验证',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => '当有人索要他们的记录并且他们的号码被隐藏(或者他们捐赠了另一个号码/电子邮件)时,请将代码发送到他们提供的号码或电子邮件;一旦验证,其记录也会显示',
  'Code validity (min)' => '代码有效期(分钟)',
  'Maximum failed attempts' => '最大失败尝试次数',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => '无法发送的代码、错误的代码和过期的代码都会计算在内。在限制范围内,该人会收到以下消息并通知团队;助理不断回答其他问题,但 24 小时内没有透露任何记录详细信息。',
  'Code to phone' => '代码到电话',
  'WhatsApp, SMS if it fails' => 'WhatsApp、短信(如果失败)',
  'WhatsApp only' => '仅限 WhatsApp',
  'SMS only' => '仅限短信',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => '如果 Flux Mail 具有 SMS 连接(例如 Netgsm),则使用 SMS。',
  'Message when verification fails' => '验证失败时的消息',
  'WhatsApp/SMS code message' => 'WhatsApp/SMS 代码消息',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => '如果为空则默认文本。变量:{kod}、{dk}、{marka}。电子邮件文本在 Flux Mail › 电子邮件模板中编辑。',
  'Site content' => '网站内容',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Let the assistant search published site content (e.g. "do you have a post about tree planting")',
  'Content types to search' => '要搜索的内容类型',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => '仅返回没有密码的已发布内容。草稿、私人内容和受密码保护的内容永远不会显示。',
  'Categories and tags never to share' => '永远不要分享的类别和标签',
  'e.g. corporate-offers, internal-notice' => '例如公司要约、内部通知',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => '名称或别名,以逗号分隔。要隐藏单个项目,请在其编辑屏幕上勾选“不要让助手共享此内容”。',
  'Team group' => '团队组',
  'WhatsApp group' => 'WhatsApp 群组',
  '— Not selected —' => '— 未选择 —',
  'Groups the line is a member of. If a group you just created is missing,' => '该线路所属的组。如果您刚刚创建的群组丢失,',
  'refresh the list' => '刷新列表',
  'Post incoming messages and replies (assistant, team, automatic) to this group' => '将收到的消息和回复(助理、团队、自动)发布到该组',
  'Send handoff notifications to this group instead of each number; the numbers above are mentioned in the message' => '向该组而不是每个号码发送切换通知;消息中提到了上述号码',
  'Last post to the group failed: ' => '上次发帖失败:',
  'Price list preview' => '价目表预览',
  'Enter an AI key and model first so the assistant can work.' => '首先输入 AI 密钥和型号,以便助手可以工作。',
  'The assistant will not reply right now: ' => '助理暂时不会回复:',
  'WhatsApp assistant' => 'WhatsApp 助手',
  'Do not let the assistant share this content' => '请勿让助手分享此内容',
  'Corrected by staff member %1$s; #%2$d was opened instead.' => '由工作人员%1$s更正; #%2$d被打开。',
  'Donation #%1$d was cancelled and #%2$d opened instead.' => '捐赠#%1$d已取消,#%2$d改为开放。',
  'Created by staff member %s via the WhatsApp assistant.' => '由工作人员%s通过 WhatsApp 助手创建。',
  'Donation opened via staff member %1$s: %2$s (#%3$d)' => '通过工作人员%1$s发起捐赠:%2$s(#%3$d)',
  'Your certificate 🌱' => '你的证书🌱',
