  '✅ Your donor paid: *%1$s* · %2$s #%3$d' => '✅ 您的捐赠者已支付: *%1$s* ·%2$s#%3$d',
  '❌ Donation cancelled: *%1$s* · %2$s #%3$d' => '❌ 捐赠取消:*%1$s* ·%2$s#%3$d',
  'Sticker' => '贴纸',
