  'Unsupported message' => '不支持的消息',
  '{a} lines added, {d} lines removed' => '添加了{a}行,删除了{d}行',
  'No AI key or model has been entered.' => '尚未输入 AI 密钥或型号。',
  'The assistant is off and does not reply to incoming messages.' => '助手已关闭并且不回复收到的消息。',
  'Test mode is on: the assistant only replies to test numbers.' => '测试模式开启:助手仅回复测试号码。',
  'Assistant activity summary' => '助理活动总结',
  'Hide details' => '隐藏详细信息',
  'Details' => '详情',
  'Spend (USD)' => '花费(美元)',
  'Questions answered' => '已回答的问题',
  'People answered' => '人们回答',
  'People directed to donate' => '人们被指示捐款',
  'Donation records created' => '已创建捐赠记录',
