  'Memory tokens · {p} contacts' => '内存令牌·{p}联系人',
  'Opted out (blocklist)' => '选择退出(黑名单)',
  'Reminders sent' => '已发送提醒',
  'Codes sent · e-mail {e} · WhatsApp {w} · SMS {s}' => '已发送代码 · 电子邮件{e}· WhatsApp{w}· 短信{s}',
  'Verified · phone {p} · e-mail {e}' => '已验证 · 电话{p}· 电子邮件{e}',
  'Code issues · wrong {w} · expired {x} · not delivered {f}' => '代码问题 ·{w}错误 ·{x}过期 · 未交付{f}',
  'Not verified, team notified' => '未经验证,已通知团队',
  'Certificates resent' => '重新发送证书',
