  'Tokens' => '代币',
  'Daily' => '每日',
  'No records in this range.' => '此范围内无记录。',
  'Replies' => '回复',
  'Handoff' => '切换',
  'Only real chats are counted; test chat and benchmark are excluded. "Confirmed" means donations created by the assistant and marked paid.' => '仅统计真实聊天;测试聊天和基准测试被排除在外。 “已确认”是指助理创建并标记为已付款的捐款。',
  'With the team / paused' => '与团队/暂停',
  'Donation record created' => '已创建捐赠记录',
  'The assistant has not replied to any chat yet.' => '助理尚未回复任何聊天内容。',
  'Load more' => '加载更多',
  'Address: {h}' => '地址:{h}',
  '{n} assistant messages' => '{n}助理消息',
  'Donation #{id}' => '捐款#{id}',
  'Version {id}' => '版本{id}',
  'Change note (e.g. Added sacrifice question)' => '更改注释(例如添加牺牲问题)',
  'Assistant instructions' => '助理指示',
  'The main text describing how the assistant talks and the flow. Prices, donation types, bank details and what is known about the contact are added automatically on every reply. {brand} becomes the organisation name and {{belge:kisa-ad}} becomes that document\'s content.' => '描述助理如何说话和流程的正文。每次回复时都会自动添加价格、捐赠类型、银行详细信息以及有关联系人的已知信息。{brand}成为组织名称,{{belge:kisa-ad}} 成为该文档的内容。',
  'Publish now' => '立即发布',
  'New version saved' => '新版本已保存',
  'Save as new version' => '另存为新版本',
  'Show the full text sent to the model' => '显示发送给模型的全文',
  'Unsaved text' => '未保存的文本',
  'Test with this text' => '使用此文本进行测试',
  'Versions' => '版本',
  'Live' => '直播',
  'Text that ships with the plugin' => '插件附带的文本',
  'Diff: live → {v}' => '差异:实时 →{v}',
  'Show diff' => '显示差异',
  'Published' => '已发表',
  'Publish' => '发布',
  'Ready-made messages sent by the server' => '服务器发送的现成消息',
  'The model does not write these; they are generated from your settings.' => '模型不会写这些;它们是根据您的设置生成的。',
  'Change in settings' => '更改设置',
  '(empty)' => '(空)',
  'Full text sent to the model (sample chat)' => '发送至模型的全文(示例聊天)',
  'Extra documents' => '额外文件',
  'Add FAQs, campaigns, planting locations and similar information as separate documents. If you write {{belge:kisa-ad}} in the instructions, the document is placed there. A document set to "read when needed" is only read when the topic comes up, which costs less for long documents.' => '将常见问题解答、活动、种植地点和类似信息添加为单独的文档。如果您在说明中写入 {{belge:kisa-ad}},则文档将放置在那里。设置为“需要时阅读”的文档仅在主题出现时才阅读,这对于长文档而言成本较低。',
  'New document' => '新文件',
  'No documents yet.' => '还没有文件。',
  'Copy to use in the instructions' => '复制以在说明中使用',
  'Delete the document “{t}”?' => '删除文件“{t}”?',
  'automatic' => '自动',
  'Edit document' => '编辑文档',
  'Short name' => '简称',
  'Content (Markdown)' => '内容(降价)',
  'Document saved' => '文档已保存',
  'in' => '在',
