  'Main model' => '主要型号',
  'Reset' => '重置',
  'Prices are input / output per 1M tokens (USD). The selected model is used only here.' => '价格为每 100 万代币的输入/输出(美元)。所选模型仅用于此处。',
  'E.g. Look at Ahmet\'s chat and make the price answer shorter. / Hand over to the team when asked about Qurban donations.' => '例如看看艾哈迈德的聊天记录,让价格答案变得更短。 / 当被问及古尔班捐款时,将其交给团队。',
  'Search sessions…' => '搜索会话...',
  '+ New session' => '+ 新会话',
