  'The live instructions changed after this session; starting a new session is recommended.' => '本次会议后,实时说明发生了变化;建议开始新的会话。',
  'Write what you want to change. If you mention a person\'s or a number\'s chat, the AI finds it, asks your permission to read it, updates the instructions and tries them itself in the test chat on the right. Publishing needs your approval.' => '写下你想改变的内容。如果您提到某人或某个号码的聊天记录,人工智能会找到它,请求您允许阅读它,更新说明并在右侧的测试聊天中自行尝试。发布需要您的批准。',
  'Draft updated' => '草稿已更新',
  'Permission to read a chat' => '读取聊天内容的权限',
  'Allow' => '允许',
  'Always allow in this session' => '在此会话中始终允许',
  'Don\'t allow' => '不允许',
  'Draft awaiting your approval' => '草案等待您的批准',
