  'The AI tries the draft here itself: it writes like a person and sees the assistant\'s answer. Nothing is sent to WhatsApp.' => '人工智能在这里自己尝试草稿:它像人一样写作并看到助理的答案。没有任何内容发送到 WhatsApp。',
  'New version published ✓' => '新版本已发布 ✓',
