  'Your {marka} verification code: {kod}' => '您的{marka}验证码:{kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => '该代码的有效期为{dk}分钟。在您与我们的 WhatsApp 聊天中输入该信息。如果您没有要求,请忽略此消息。',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => '出了点问题;我们的团队会尽快与您联系🌱 同时,如有其他问题,请随时询问。',
  'Verification attempt failed (%1$d/%2$d): %3$s' => '验证尝试失败(%1$d/%2$d):%3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => '该人想查看自己的记录,但无法核实; someone from the team should get in touch',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => '无法发送电子邮件(检查 Flux Mail › SMTP 设置)',
  'The assistant sent a verification code for %1$s (%2$s).' => '助手发送了%1$s(%2$s) 的验证码。',
  'code expired' => '代码已过期',
  'wrong code' => '错误代码',
  'The person verified the code for %s; it is added to their record lookups.' => '该人验证了%s的代码; it is added to their record lookups.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => '克劳德模型无法读取音频;在设置 › AI › 语音消息模型中选择支持音频的 OpenRouter 模型。',
  'The audio could not be transcribed.' => '音频无法转录。',
  'The audio file could not be read.' => '无法读取音频文件。',
  'Voice message (%1$s) transcribed: %2$s' => '语音消息 (%1$s) 转录:%2$s',
  'Voice message (%1$s) could not be processed: %2$s' => '无法处理语音消息 (%1$s):%2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => '此操作在官方 WhatsApp Cloud API 线路上不可用。',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'WhatsApp 24 小时规则:联系人在过去 24 小时内没有写信,因此 Cloud API 不会发送自由格式消息;只能发送经过批准的模板。他们写完后再试一次。',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Cloud API 行需要 Flux Mail 1.10.0 或更高版本。',
  'The Cloud API cannot send to this address (hidden number or group).' => 'Cloud API 无法发送到此地址(隐藏号码或群组)。',
  'Could not reach the Cloud API account (İletişim › Connections).' => '无法访问云 API 帐户(?letişim › 连接)。',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Cloud API 线路没有二维码;该帐户是在 îletişim › Connections 中设置的。',
  'The file could not be prepared.' => '无法准备该文件。',
  'Flux AI has no image support.' => 'Flux AI 没有图像支持。',
  'The image could not be rendered.' => '无法渲染图像。',
  'The assistant\'s image could not be sent: ' => '助理图片无法发送:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => '您好{first_name},我们已创建您的捐款记录:{donation},总计{amount}。{bank}付款后,您可以将收据发送至此处。谢谢。',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => '您好{first_name},您的捐款已记录:{donation},总计{amount}。' . chr(10) . '' . chr(10) . '感谢您的支持。',
  'The plugin that would run this scenario is inactive.' => '运行此场景的插件处于非活动状态。',
  'This user is not allowed to use the staff tools.' => '该用户无权使用员工工具。',
  '%1$s linked this chat to staff member %2$s' => '%1$s将此聊天链接到工作人员%2$s',
  '%s removed the staff link of this chat' => '%s删除了此聊天的员工链接',
  'Chat linked to staff member' => '与工作人员关联的聊天',
  'Staff link removed' => '员工链接已删除',
  '— Not staff —' => '— 不是工作人员 —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp 隐藏了此人的号码,因此助理无法通过号码识别工作人员。如果此人在您的团队中,请在此处链接他们,助理将打开员工工具。',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => '助理通过员工 Flux 角色档案中的号码来识别员工。如果号码不匹配,您可以在此处链接;在与已知号码聊天时,号码排在第一位。',
  'This channel is not available right now.' => '该频道目前不可用。',
  'Site chat' => '现场聊天',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => '来自 WhatsApp、网站聊天和其他渠道的所有消息都会实时显示在这里。选择左侧的聊天。',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'WhatsApp(Evolution API)呼叫中心:查看实时传入和传出消息、开始新聊天、预设回复、标签、作业、内部注释、自动回复;通过聊天注册捐赠(Flux Donate)和证书(Flux Certificates),收据匹配。 OpenRouter 的人工智能响应建议和自动捐赠助手。',
