  'Bu sayfaya erişim yetkiniz yok.' => '您没有访问此页面的权限。',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => '监视助手处理的聊天,编辑其说明和文档,并在发布之前测试更改。',
