  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'AI需要Flux AI & MCP插件;安装并激活它,然后在 Flux AI & MCP › 设置中输入密钥。',
  'Yapay zekâ modeli seçilmemiş.' => '未选择 AI 模型。',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'Flux AI 中尚未输入 Anthropic (Claude) 密钥。',
