  'Model listesi için Flux AI & MCP eklentisi gerekli.' => '模型列表需要 Flux AI & MCP 插件。',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Flux 呼叫中心:AI 功能(建议、助手、收据阅读、语音消息、摘要)需要 Flux AI 和 MCP 插件。安装并激活它;保存在呼叫中心的密钥会自动移至那里。',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux 呼叫中心:Flux AI 中已保存另一个%s密钥,并且是正在使用的密钥。旧的呼叫中心密钥未移动且不再使用。',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Flux 呼叫中心:AI 按键已移至 Flux AI。从现在开始,密钥、支出限额和日志均在 Flux AI 中管理;型号选择保留在呼叫中心。',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'Flux Donate 插件未激活;助理从中获取捐赠类型和价格。',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'Flux Donate 中没有开放的捐赠类型(在捐赠类型页面上打开一个)。',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => '为助理选择的捐赠类型已关闭或没有价格;选择开放类型或将选择留空。',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => '所有公开的捐赠类型都没有价格(Flux Donate › 捐赠类型 › 期权价格)。',
