  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => '我们已收到您的收据,谢谢您🌱您的捐款已确认。',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => '我们已经收到此收据,谢谢您🌱我们会尽快回复您有关付款的信息。',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => '该收据似乎之前已上传到我们的系统。同一张收据不能用于第二次捐赠。如果您进行了不同的付款,请发送收据;我们的团队也会检查。',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => '我们收到了您的收据。上面的金额 (%1$s) 似乎与您的捐款金额 (%2$s) 不符。你能检查一下吗?如果您进行了不同的付款,您可以写在这里;我们的团队也会看一看。',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => '我们已收到您的收据,但收据上的收件人似乎不是我们协会。捐款仅以“%s”名义存入我们的帐户。你能检查一下吗?我们的团队也会看一下。',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => '我们已收到您的收据,但收据上的收件人似乎与我们的帐户不符。你能检查一下吗?我们的团队也会看一下。',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => '您发送的文件看起来不像付款收据。如果您已付款,您可以在此处发送收据或付款屏幕的屏幕截图。',
