  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => '收件人号码来自用户 › 个人资料 › WhatsApp 号码;用户的权限 › 角色和访问(接收报告、查看总体报告、管理报告)。报告在选定的时间发出;如果没有服务器调度程序,它们将在下次站点访问或聊天面板使用时发送。',
