  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => '此联系人通过隐藏的 WhatsApp 号码 (@lid) 进行写入,Evolution API(版本%s)无法发送到此地址。将Evolution API服务器更新到2.3或更高版本;如果联系人的真实号码到达,插件就会发送到那里。',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => '此联系人通过隐藏的 WhatsApp 号码 (@lid) 进行写入,Evolution API 无法发送到此地址。将Evolution API服务器更新到2.3或更高版本;如果联系人的真实号码到达,插件就会发送到那里。',
