  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(旧:回复隐藏号码(@lid)联系人可能会失败,更新至2.3或更高版本)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'Webhook 未指向此站点。按“设置网络钩子”。',
