  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => '导入最近的聊天记录,这可能需要一段时间......',
  'Evolution\'da kayıtlı mesaj: %s' => 'Evolution 中存储的消息:%s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution 不存储消息,因此无法加载较旧的消息。在 Evolution 服务器上,将 DATABASE_SAVE_DATA_NEW_MESSAGE 和 DATABASE_SAVE_DATA_HISTORIC 设置为 true;对于较旧的对话,当您使用 QR 重新连接线路时,请在实例设置中保持“同步完整历史记录”处于打开状态。',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => '%1$s聊天、导入%2$s消息 ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => '通过 WhatsApp 扫描此代码 › 链接的设备 › 链接设备。',
  'Eşleştirme kodu:' => '配对代码:',
  'Bu hat zaten bağlı ✓' => '该线路已连接 ✓',
  'Önce ayarları kaydedin.' => '先保存设置。',
  'Hata:' => '错误:',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => '删除这个连接吗?聊天记录被保留。',
  'Yapay zekâya soruluyor…' => '询问人工智能...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => '工作 ✓(%2$s毫秒):%1$s',
  'Önce anahtarı ve modeli kaydedin.' => '首先保存密钥和模型。',
  'Bağlantılar' => '连接',
  'Otomatik yanıtlar' => '自动回复',
  'Yapay zekâ ve asistan' => 'AI与助手',
  'Sistem kontrolü' => '系统检查',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => '连接您的 WhatsApp 线路,管理自动回复和标签。',
  'Sohbetleri aç' => '打开聊天室',
  'Ayarlar kaydedildi.' => '设置已保存。',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => '呼叫中心所需的连接和设置。显示保存状态;使用每个选项卡上的“测试”按钮进行实时检查。主题的系统检查屏幕上的其他插件也会出现相同的检查。',
  'WhatsApp hatları' => 'WhatsApp 线路',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => '消息通过 Evolution API 发送和接收。 WhatsApp 连接在 Flux Mail 中管理;在这里选择使用哪一个。 URL 和 API 密钥保留在那里,因此当它们发生更改时,您无需在此处更新它们。',
  'İletişim › Bağlantılar' => '通讯 › 连接',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => '消息通过 Evolution API 发送和接收。如果在 Flux 证书中设置了 Evolution 提供程序,您可以选择相同的连接; URL 和 API 密钥保留在那里。',
  'Hat ekle' => '添加行',
  'Kurulum adımları' => '设置步骤',
  'Hattı ekleyip kaydedin.' => '添加该行并保存。',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => '使用“测试连接”来查看 Evolution 是否可达。如果线路未链接,请选择“使用 QR 连接”并从手机扫描。',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => '按“设置网络钩子”。传入的消息以及从手机和 Flux 证书发送的消息都会实时显示在此处。',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => '可以选择通过“导入最近的聊天记录”引入过去的消息。',
  'bağlı' => '已连接',
  'bağlanıyor' => '连接',
  'bağlı değil' => '未连接',
  'sunucuda yok' => '不在服务器上',
  'ulaşılamıyor' => '无法到达的',
  'Flux Mail bağlantısı: %s' => 'Flux 邮件连接:%s',
  'Flux Mail bağlantısı #%d (bulunamadı ya da kapalı)' => 'Flux 邮件连接 #%d(未找到或已禁用)',
  'Flux Certificates sağlayıcısını kullan: %s' => '使用 Flux 证书提供商:%s',
  'Ayrı Evolution API bilgisi gir' => '输入单独的 Evolution API 详细信息',
  'Hat adı (ör. Ana hat)' => '线路名称(例如主线)',
  'Bağlantı bilgisi' => '连接详情',
