  'QR ile bağla' => '通过二维码连接',
  'QR, durum ve hesaplar: İletişim › Bağlantılar' => '二维码、状态和帐户:通讯 › 连接',
  'Webhook\'u kur' => '设置网络钩子',
  'Son sohbetleri içe aktar' => '导入最近的聊天记录',
  'Kaydettikten sonra webhook adresi ve test düğmeleri görünür.' => '保存后将出现 webhook URL 和测试按钮。',
  'Görünüm' => '外观',
  'Panel başlığı' => '面板标题',
  'Boş bırakılırsa site adı. {brand} değişkeni de bunu kullanır.' => '站点名称(如果为空)。{brand}变量也使用它。',
  'Vurgu rengi' => '强调色',
  'Çalışma şekli' => '行为',
  'Sohbet açılınca karşı tarafa okundu bilgisi (mavi tik) gönder' => '打开聊天时发送已读回执(蓝色勾号)',
  'Mesajın başına temsilci adını ekle (*Ad:*)' => '在消息中添加代理姓名前缀 (*Name:*)',
  'Temsilciler yalnız kendine atanan ve atanmamış sohbetleri görsün (yöneticiler hepsini görür)' => '客服人员只能看到分配给他们的聊天和未分配的聊天(管理员查看全部)',
  'WhatsApp grup mesajlarını da göster' => '还显示 WhatsApp 群组消息',
  'Yeni arayüz (deneysel): Sohbetler sayfası masaüstü ve mobil uygulamayla aynı ekranla açılır' => '新界面(实验性):聊天页面打开时与桌面和移动应用程序在同一屏幕上',
  'Canlı güncelleme sıklığı (sn)' => '实时更新间隔(秒)',
  'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10). Sekme arka plandayken dakikada bir, hata olursa giderek seyrekleşir.' => '打开的选项卡按此时间间隔检查新消息(建议 10 次)。在后台选项卡中,它每分钟检查一次,出现错误后检查频率会降低。',
  'Temsilciler' => '代理商',
  'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.' => '授予用户%s角色;他们只能看到聊天屏幕,无法打开设置。管理员始终具有访问权限。',
  'Yeni kullanıcı ekle' => '添加新用户',
  'Veri' => '数据',
  'Eklenti silinirken tüm sohbetleri, mesajları ve medya dosyalarını da sil' => '删除插件时也会删除所有聊天、消息和媒体文件',
  'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.' => '媒体文件保存在 wp-content/uploads/flx-chat 中,禁止外部访问。当网站迁移时,它们会随着上传内容一起移动。',
  'Pzt' => '周一',
  'Sal' => '星期二',
  'Çar' => '周三',
  'Per' => '星期四',
  'Cum' => '周五',
  'Cmt' => '星期六',
  'Paz' => '太阳',
  'Karşılama mesajı' => '欢迎留言',
  'Bize ilk kez yazan kişiye otomatik gönder' => '自动发送给第一次给我们写信的人',
  'Mesai dışı yanıtı' => '离开消息',
  'Mesai saatleri dışında gelen mesajlara otomatik yanıt ver' => '自动回复工作时间以外收到的消息',
  'Mesai günleri' => '工作日',
  'Başlangıç' => '开始',
  'Bitiş' => '结束',
  'Aynı kişiye en fazla (saatte bir)' => '每次联系最多(小时)一次',
  'Saat dilimi: %1$s. Şu an: %2$s.' => '时区:%1$s。现在:%2$s。',
  'mesai içi' => '营业时间内',
  'mesai dışı' => '营业时间外',
  'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.' => '{first_name}、{name}、{brand}、{site}、{date}变量可以在文本中使用。',
  'Sohbet etiketleri' => '聊天标签',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => '标记聊天并过滤列表(例如捐赠、投诉、跟进)。',
  'Etiket ekle' => '添加标签',
  'Etiket adı' => '标签名称',
  'Sohbetten kayıt oluşturma' => '从聊天中创建记录',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => '聊天标题中的按钮创建捐赠记录(Flux Donate)和证书(Flux Certificates),并且传入收据与记录匹配。如果未安装插件,其按钮将被隐藏。',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => '代理人可以创建捐赠记录并匹配收据',
  'Temsilciler sertifika oluşturup gönderebilsin' => '代理可以创建和发送证书',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => '在消息框上方显示快速回复气泡',
  'Bağış mesajları' => '捐款留言',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => '创建记录时发送给该人员的就绪文本(发送前可编辑)。如果留空,则使用默认文本。',
  'Ödeme bekleniyor (havale sözü)' => '等待付款(承诺转账)',
  'Bağış alındı' => '收到捐款',
  'Dekont onaylandı' => '已确认收货',
  'Banka bilgisi ({bank})' => '银行详细信息 ({bank})',
  'Alıcı adı, banka, IBAN' => '收款人姓名、银行、IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => '如果为空,则使用 WooCommerce › 付款 › 银行转帐中的帐户。',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => '变量:{first_name}、{name}、{donation}、{amount}、{quantity}、{bank}、{certificate_link}、{agent}、{brand}、{date}。',
  'Yapay zekâ bağlantısı' => '人工智能连接',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => '密钥、提示缓存、支出限制和使用日志来自 Flux AI & MCP 插件;呼叫中心的所有人工智能请求都经过它。型号选择留在这里;如果字段为空,则使用 Flux AI 中为此插件选择的模型(或默认模型)。',
  'Flux AI ayarlarını aç' => '打开 Flux AI 设置',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'AI 需要 Flux AI & MCP 插件。安装并激活它,然后在 Flux AI & MCP › 设置中输入 OpenRouter 和/或 Anthropic 密钥。在此之前,建议、助手、收据阅读、语音消息和摘要都将关闭。',
  'Yaratıcılık (0–1)' => '创造力 (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => '较低的值提供更一致的答复,较高的值提供更自由的答复。推荐0.4。',
  'Model (öneriler için)' => '型号(供建议)',
  'Asistan modeli (isteğe bağlı)' => '助理模型(可选)',
  'Yukarıdaki model' => '以上型号',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => '仅列出支持工具的型号。',
  'Dekont okuma modeli (isteğe bağlı)' => '收据读取模型(可选)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => '如果所选模型无法读取图像,则会自动使用廉价的视觉模型。',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => '本月 (%1$s):%2$s请求、%3$s代币,约 $%4$s。',
  'Cevap önerisi' => '回复建议',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => '在消息框上方,从对话中建议下一条消息。代理单击“发送”或将其放入“编辑”框中。建议永远不会单独发送。',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => '当该人发送最后一条消息时,自动准备建议(如果关闭,请使用 ✨ 按钮询问)',
  'Kurum bilgisi ve üslup' => '组织信息和基调',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => '例如我们协会在伊斯坦布尔种植树苗。每年 11 月至 3 月期间进行种植。捐赠后,证书将通过 WhatsApp 发送。使用温暖但正式的语气。',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => '建议和助手用这个。捐赠类型、价格、银行详细信息和快速回复都会自动添加。',
  'Öneri sağlayıcısı' => '建议提供者',
  'Bağış asistanı (otomatik cevap)' => '捐款助手(自动回复)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => '启用后,助手会自行回复:它会打招呼,询问姓名,发送捐赠选项和价格,可选择收集电子邮件和“以谁的名义”,并在每次更改后要求确认。确认后,它会在 Flux Donate 中打开“等待付款”记录,并将捐赠链接、收件人、IBAN 和参考信息作为单独的消息发送。如果该主题留下捐款,则会将聊天交给团队。',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'Flux Donate 插件未激活;助理无法创建捐赠记录。',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => '说明、文档、AI 聊天和测试聊天',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => '打开捐赠助手(取消勾选即可在所有地方将其关闭)',
  'Hangi sohbetlerde cevap versin' => '它应该回复哪些聊天',
  'Tüm sohbetlerde (önerilen)' => '在所有聊天中(推荐)',
  'Temsilciye atanmamış sohbetlerde' => '在未分配给客服人员的聊天中',
  'Yalnız mesai saatleri dışında' => '仅限工作时间以外',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => '当客服人员在聊天中(通过面板或电话)进行书写时,助理会在下面的时间内保持安静。使用聊天标题中的助手按钮在每次聊天时打开或关闭它。',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => '测试模式:仅回复以下号码',
  'Test numaraları' => '测试号码',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => '用逗号或换行符分隔。测试模式关闭时不使用。',
  'Temsilci yazınca susma (saat)' => '代理写信后安静(小时)',
  'Fiyat listesindeki adetler' => '价格表中的数量',
  'Konuşma geçmişi (saat)' => '对话历史记录(小时)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => '在回复之前,助理会阅读该时段的所有消息。',
  'Asistanın sunduğu bağış türleri' => '助理提供的捐赠类型',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => '如果未选择任何类型,则提供所有开放类型。当在 Flux Donate 中打开新类型时,助手也会知道。',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => '收据预检查:当联系人发送收据时,AI 将金额、收件人和 IBAN 与捐赠进行比较,告诉联系人结果,将文件附加到捐赠记录中,并将聊天交给团队进行最终批准(不标记为已付款)',
  'Fiyat listesinin son satırı' => '价格表的最后一行',
  'Ödeme bilgileri' => '付款详情',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => '如果收件人和 IBAN 为空,则使用 WooCommerce › 付款 › 银行转帐中的内容(订单上显示的帐户)。仅当助理应使用不同的帐户时才填写它们。',
  'Alıcı adı' => '收件人姓名',
  'Havale açıklaması' => '转账说明',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => '变量:{type}、{name}、{amount}、{quantity}',
  'Bağış sayfası adresi' => '捐款页面网址',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => '所选类型和数量将添加到链接 (?flxb_opt=...&flxb_qty=...)。',
  'Ödeme bilgilerinden sonraki mesaj' => '付款详情后留言',
  'Bağış iptali onay sorusu' => '取消捐赠问题',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => '助理仅会在经本人确认后取消未付款的捐款。空=默认文本。变量:{bagis}、{tutar}。',
  'Günlük sınır dolunca gönderilen mesaj' => '达到每日限额时发送的消息',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => '当聊天达到当日回复上限时发送一次;聊天将交给团队。从聊天的 ⋮ 菜单重置它 › 助理使用。',
  'Ekibe devrederken gönderilen mesaj' => '移交团队时发送的消息',
  'Asistan cevap veremezse giden mesaj' => '助理无法接听时发送的消息',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => '如果AI失败、达到时间限制或队列太长,则会发送此消息并将聊天交给团队;这个人永远不会没有答案。',
  'Bekleme mesajından önce en az (sn)' => '保留消息之前的最短等待时间',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => '直到该人的消息发送后这么多秒才会发送保留消息;与此同时,助理重试。',
  'Bir cevabın en uzun süresi (sn)' => '一次回答的最长时间(秒)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger 可以在约 60 秒内削减请求;建议50。',
  'Devirde bildirim gidecek numaralar' => '交接时通知的号码',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => '当助理将聊天交给团队时,一条 WhatsApp 消息将从同一行发送到这些号码:联系人的姓名、电话、原因、最后一条消息和面板链接。用逗号或换行符分隔。助理不会与这些号码交谈。',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => '当联系人写下其中之一时,助理会立即发送上面的移交消息,并在该聊天中关闭。如果留空,则使用示例列表。',
  'Asistana ek talimatlar' => '给助理的额外说明',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => '例如科贾埃利种植了树苗。捐赠确认后将发送证书。',
  'Kişi mesaj istemeyince gönderilen son mesaj' => '联系人选择退出时的最后一条消息',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => '如果有人写了“不要给我发消息”之类的内容,助手会发送此消息并将其列入黑名单。被列入黑名单的人无法收到 WhatsApp、电子邮件或短信;管理“聊天”下的列表 › ☰ › 阻止列表。',
  'Kişi hafızası ve arka plan işleri' => '联系内存和后台作业',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => '联系人记忆:助手记住持久的细节(地址形式、亲属姓名、号码、偏好);过期聊天记录已汇总',
  'Sohbet kaç saat sessiz kalınca özetlensin' => '安静(几个小时)后总结一次聊天',
  'Aynı anda en fazla iş' => '同时最大作业数',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => '可以同时回答多少人。助理回复始终优先;当有人正在回答或等待时,摘要不会开始。每个作业使用一名 PHP 工作人员:在共享主机上,保持在站点总工作人员限制的一半以下(例如 60 名工作人员中的 20-30 名)。',
  'Yalnız cevaplara ayrılan işçi' => '保留回复的工作人员',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => '很多工人从来不做总结或提醒。',
  'Özet saatleri' => '总结时间',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => '汇总仅在这些时间之间运行(手动“立即汇总”除外)。如果两者相同,则任何时间。',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => '当有人发送语音消息时,助手会将其转换为文本并回复(文本也会作为系统线路显示在面板中)',
  'En uzun ses (sn)' => '最长语音消息(秒)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => '对于较长的消息,助理会说“语音消息太长,我们无法收听”。',
  'Sesli mesaj modeli (isteğe bağlı)' => '语音留言模型(可选)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => '廉价音频模型(Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => '必须是接受音频的 OpenRouter 模型(Claude 不接受)。需要 OpenRouter 密钥。',
  'Görseller' => '图片',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => '使用 Flux AI 图像渲染器(Flux AI 和 MCP › 设置 › 图像)。',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => '服务器上没有图像渲染器:在 Flux AI & MCP › 设置 › 图像中输入 Gotenberg 地址或安装 Imagick (SVG)。在此之前,助手不会绘制图像。',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => '安装 Flux AI 0.2.0 或更高版本后即可工作。',
  'Başkası adına bağış' => '代表某人捐款',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => '如果捐款是以他人名义进行的,并且提供了他们的号码(联系卡或键入的号码),请在付款获得批准后将证书发送到 WhatsApp 上的该号码',
  'Sertifikadan önce giden mesaj' => '证书之前发送的消息',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => '然后发送来自 Flux 证书的 WhatsApp 证书消息。变量:{ad}、{bagisci}、{bagis}、{brand}。',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => '如果有人询问,助理会设置提醒(例如“每月提醒我种植树苗”、“每月向我发送您的最新项目”、“每月向我要一棵树苗”);当到期时,助理会编写并发送消息',
  'Saat söylenmezse' => '当没有给定时间时',
  'Kişi başına en fazla' => '每人最多',
  'Personel (Flux Roles)' => '员工(通量角色)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => '安装 Flux Roles 1.1.0 后即可使用:在个人资料 › WhatsApp 号码中设置号码的用户将根据其权限获得额外的辅助工具。',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => '经许可,为员工提供额外的辅助工具(代表有付款链接的人、我的捐赠者、一般报告)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => '当他们推荐的捐款已支付或取消时,通过 WhatsApp 通知工作人员',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => '工作人员向捐赠者发出的第一条捐赠信息',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => '您好{ad}🌱 我们已收到您通过{personel}发出的{bagis}捐款请求。您可以通过以下详细信息进行付款。',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => '随后是付款链接和银行详细信息。变量:{ad}、{adsoyad}、{personel}、{bagis}。',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => '当工作人员推荐的捐款支付并制作证书后,也通过 WhatsApp 将其发送给工作人员(就像捐赠者一样)',
  'Personele sertifikadan önce giden mesaj' => '证书前发送给工作人员的消息',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => '变量:{ad}、{bagisci}、{bagis}、{no}、{brand}。',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => '工作人员可以重新发送捐赠证书多少次',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => '助理会列出收件人并在发送前要求确认。 0:关闭。',
  'Kayıt sorgusunda kod doğrulama' => '记录查找的代码验证',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => '当有人索要他们的记录并且他们的号码被隐藏(或者他们捐赠了另一个号码/电子邮件)时,请将代码发送到他们提供的号码或电子邮件;一旦验证,其记录也会显示',
  'Kod geçerliliği (dk)' => '代码有效期(分钟)',
  'En fazla başarısız deneme' => '最大失败尝试次数',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => '无法发送的代码、错误的代码和过期的代码都会计算在内。在限制范围内,该人会收到以下消息并通知团队;助理不断回答其他问题,但 24 小时内没有透露任何记录详细信息。',
  'Telefona kod' => '代码到电话',
  'WhatsApp, gitmezse SMS' => 'WhatsApp、短信(如果失败)',
  'Yalnız WhatsApp' => '仅限 WhatsApp',
  'Yalnız SMS' => '仅限短信',
  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => '如果 Flux Mail 具有 SMS 连接(例如 Netgsm),则使用 SMS。',
  'Doğrulama yapılamazsa giden mesaj' => '验证失败时的消息',
  'WhatsApp/SMS kod mesajı' => 'WhatsApp/SMS 代码消息',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => '如果为空则默认文本。变量:{kod}、{dk}、{marka}。电子邮件文本在 Flux Mail › 电子邮件模板中编辑。',
  'Sitedeki içerikler' => '网站内容',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'Let the assistant search published site content (e.g. "do you have a post about tree planting")',
  'Aranacak içerik türleri' => '要搜索的内容类型',
  'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.' => '仅返回没有密码的已发布内容。草稿、私人内容和受密码保护的内容永远不会显示。',
  'Hiç paylaşılmayacak kategori ve etiketler' => '永远不要分享的类别和标签',
  'ör. kurumsal-teklifler, ic-duyuru' => '例如公司要约、内部通知',
  'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.' => '名称或别名,以逗号分隔。要隐藏单个项目,请在其编辑屏幕上勾选“不要让助手共享此内容”。',
  'Ekip grubu' => '团队组',
  'WhatsApp grubu' => 'WhatsApp 群组',
  '— Seçilmedi —' => '— 未选择 —',
  'Hattın üye olduğu gruplar. Yeni açtığınız grup görünmüyorsa' => '该线路所属的组。如果您刚刚创建的群组丢失,',
  'listeyi yenileyin' => '刷新列表',
  'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz' => '将收到的消息和回复(助理、团队、自动)发布到该组',
  'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir' => '向该组而不是每个号码发送切换通知;消息中提到了上述号码',
  'Gruba son gönderim başarısız: ' => '上次发帖失败:',
  'Fiyat listesi önizlemesi' => '价目表预览',
  'Asistanın çalışması için önce yapay zekâ anahtarı ve model girin.' => '首先输入 AI 密钥和型号,以便助手可以工作。',
  'Asistan şu an konuşmaz: ' => '助理暂时不会回复:',
  'WhatsApp asistanı' => 'WhatsApp 助手',
  'Asistan bu içeriği kişilerle paylaşmasın' => '请勿让助手分享此内容',
  'Personel %1$s düzeltti; yerine #%2$d açıldı.' => '由工作人员%1$s更正; #%2$d被打开。',
  'Bağış #%1$d iptal edildi, yerine #%2$d açıldı.' => '捐赠#%1$d已取消,#%2$d改为开放。',
  'Personel %s WhatsApp asistanıyla oluşturdu.' => '由工作人员%s通过 WhatsApp 助手创建。',
  'Personel %1$s aracılığıyla bağış kaydı açıldı: %2$s (#%3$d)' => '通过工作人员%1$s发起捐赠:%2$s(#%3$d)',
  'Sertifikanız 🌱' => '你的证书🌱',
  'Personel %1$s sertifikayı WhatsApp\'tan yeniden gönderdi: %2$s' => '工作人员%1$s在 WhatsApp 上重新发送证书:%2$s',
  '✅ Bağışçınız ödedi: *%1$s* · %2$s #%3$d' => '✅ 您的捐赠者已支付: *%1$s* ·%2$s#%3$d',
  '❌ Bağış iptal edildi: *%1$s* · %2$s #%3$d' => '❌ 捐赠取消:*%1$s* ·%2$s#%3$d',
  'Çıkartma' => '贴纸',
  'Anket' => '民意调查',
  'Desteklenmeyen mesaj' => '不支持的消息',
  '{a} satır eklendi, {d} satır çıkarıldı' => '添加了{a}行,删除了{d}行',
  'Yapay zekâ anahtarı ya da modeli girilmemiş.' => '尚未输入 AI 密钥或型号。',
  'Asistan kapalı; gelen mesajlara cevap vermiyor.' => '助手已关闭并且不回复收到的消息。',
  'Test modu açık: asistan yalnız test numaralarına cevap veriyor.' => '测试模式开启:助手仅回复测试号码。',
  'Asistanın çalışma özeti' => '助理活动总结',
  'Detayı gizle' => '隐藏详细信息',
  'Detay' => '详情',
  'Harcama (USD)' => '花费(美元)',
  'Cevaplanan soru' => '已回答的问题',
  'Cevap verilen kişi' => '人们回答',
  'Bağışa yönlendirilen kişi' => '人们被指示捐款',
  'Açılan bağış kaydı' => '已创建捐赠记录',
  'Onaylanan bağış · {a}' => '已确认的捐赠 ·{a}',
  'Okunan dekont · ✓{a} ✕{b}' => '收据已读 · ✓{a}✕{b}',
  'Ekibe devir' => '移交给团队',
  'Hafıza token · {p} kişi' => '内存令牌·{p}联系人',
  'Mesaj istemedi (kara liste)' => '选择退出(黑名单)',
  'Gönderilen hatırlatıcı' => '已发送提醒',
  'Gönderilen kod · e-posta {e} · WhatsApp {w} · SMS {s}' => '已发送代码 · 电子邮件{e}· WhatsApp{w}· 短信{s}',
  'Doğrulanan · telefon {p} · e-posta {e}' => '已验证 · 电话{p}· 电子邮件{e}',
  'Kod sorunu · yanlış {w} · süresi doldu {x} · gitmedi {f}' => '代码问题 ·{w}错误 ·{x}过期 · 未交付{f}',
  'Doğrulanamadı, ekibe bildirildi' => '未经验证,已通知团队',
  'Yeniden gönderilen sertifika' => '重新发送证书',
  'Asistanın iptal ettiği bağış' => '助理取消捐款',
  'Yeniden gönderilen ödeme linki' => '付款链接已重新发送',
  'Token: {i} giriş / {o} çıkış · {c} istek · {m} mesaj gönderildi' => '令牌:{i}输入 /{o}输出 ·{c}请求 · 发送的{m}消息',
  '{n} bağış ödeme bekliyor' => '{n}捐款等待付款',
  '{n} hata' => '{n}错误',
  '{n} sohbet özetlendi' => '{n}聊天摘要',
  'Sayaçlar {d} tarihinden beri' => '自{d}以来的计数器',
  '30 sn\'de bir yenilenir' => '每 30 秒刷新一次',
  'Modeller' => '型号',
  'En çok hafızası olan kişiler' => '记忆最多的联系人',
