  'Mesajlar (sırayla)' => '留言(按顺序)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => '可以使用{tur}、{birim}和{brand}。如果只有客户留言,助理会依次回复。如果您添加助理消息,它将成为一个延续场景:书面历史记录按原样给出,助理仅回复最后一条客户消息。',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => '例如付款信息、取消捐赠、收据检查。不会检查此站点上禁用的工具。',
