  'Flux Mail bağlantısı kullanılıyor: %s.' => '使用 Flux 邮件连接:%s。',
  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => '仍在 Flux 证书中使用旧的提供程序;将连接移至 Flux Mail 并在此处选择它。',
  'Flux Certificates\'daki Evolution sağlayıcısı kullanılıyor.' => '使用 Flux 证书中的 Evolution 提供程序。',
