  '%s: hat durumu' => '%s:线路状态',
  'Telefon bağlı (son bilgi %s).' => '电话已连接(上次查看%s)。',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => '尚未测试。按“测试连接”。',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => '电话未连接(状态:%1$s、%2$s)。通过“使用 QR 连接”重新连接。',
  '%s: Evolution API sürümü' => '%s:进化 API 版本',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'Evolution API%s正在使用中。回复隐藏号码 (@lid) 联系人可能会失败;将服务器更新到2.3或更高版本。',
  '%s: webhook (gelen mesajlar)' => '%s:网络钩子(传入消息)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => '进化还没有发生任何事件;传入的消息不会显示在面板中。按“设置网络钩子”。',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => '最后一个事件到达%s。线路可能只是安静;向自己发送消息或再次设置 Webhook 以确定。',
  'Son olay %s geldi.' => '最后一个事件到达%s。',
  'Flux Mail entegrasyonu' => 'Flux 邮件集成',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => '活动:WhatsApp 连接取自通信 › 连接。',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux 邮件未激活;连接取自 Flux 证书或此插件。',
  'Flux Certificates entegrasyonu' => 'Flux证书集成',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => '活动:可以通过聊天创建和发送证书。',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Flux 证书未激活;聊天中的证书操作已关闭。',
  'Flux Donate entegrasyonu' => '通量捐赠整合',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => '活跃:可以通过聊天查看捐赠记录、收据匹配和助手。',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => '通量捐赠未激活;捐赠记录、收据匹配和捐赠助理均已关闭。',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'Flux AI & MCP插件未安装;人工智能功能(建议、助手、收据阅读、语音消息、摘要)已关闭。安装 Flux AI 并在那里输入密钥。',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'Flux AI 中尚未输入密钥;消息建议和助手已关闭。',
  'Anahtar var ama model seçilmemiş.' => '密钥已保存,但未选择型号。',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => '尚未在 Flux AI 中输入所选模型 (%s) 的提供商密钥。',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => '密钥已保存,型号:%s。使用“测试连接”进行实时检查。',
  'Bağış asistanı' => '捐赠助理',
  'Kapalı.' => '关闭。',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'AI 密钥或模型丢失。',
  'Açık ama konuşmuyor: ' => '已开启但未回复:',
