  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%s不支持工具;为助手选择一个支持工具的模型。',
  'Dekont okuma modeli' => '收据读取模型',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%s无法读取图像;收据预检查将不起作用。选择具有图像功能的收据读取型号。',
  'Asistanın ödeme bilgileri' => '助理付款详情',
  'Alıcı adı ve IBAN tanımlı.' => '收件人姓名和 IBAN 设置。',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => '收件人姓名或 IBAN 缺失;确认后无法发送银行详细信息。',
  'Bağış sayfası linki' => '捐赠页面链接',
