  'Arka plan istekleri' => '后台请求',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => '该站点无法向自身发送后台请求(%1$s:%2$s)。排队回复和基准可能会缓慢移动;安全插件或服务器防火墙可能会阻止 /wp-json/flx-chat/ 请求。',
  'hata' => '错误',
  'uyarı' => '警告',
  'tamam' => '好的',
  '{marka} doğrulama kodunuz: {kod}' => '您的{marka}验证码:{kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => '该代码的有效期为{dk}分钟。在您与我们的 WhatsApp 聊天中输入该信息。如果您没有要求,请忽略此消息。',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => '出了点问题;我们的团队会尽快与您联系🌱 同时,如有其他问题,请随时询问。',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => '验证尝试失败(%1$d/%2$d):%3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => '该人想查看自己的记录,但无法核实; someone from the team should get in touch',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => '无法发送电子邮件(检查 Flux Mail › SMTP 设置)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => '助手发送了%1$s(%2$s) 的验证码。',
  'kodun süresi doldu' => '代码已过期',
