  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => '该人验证了%s的代码; it is added to their record lookups.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => '克劳德模型无法读取音频;在设置 › AI › 语音消息模型中选择支持音频的 OpenRouter 模型。',
  'Ses metne çevrilemedi.' => '音频无法转录。',
  'Ses dosyası okunamadı.' => '无法读取音频文件。',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => '语音消息 (%1$s) 转录:%2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => '无法处理语音消息 (%1$s):%2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => '此操作在官方 WhatsApp Cloud API 线路上不可用。',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'WhatsApp 24 小时规则:联系人在过去 24 小时内没有写信,因此 Cloud API 不会发送自由格式消息;只能发送经过批准的模板。他们写完后再试一次。',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Cloud API 行需要 Flux Mail 1.10.0 或更高版本。',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'Cloud API 无法发送到此地址(隐藏号码或群组)。',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => '无法访问云 API 帐户(?letişim › 连接)。',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Cloud API 线路没有二维码;该帐户是在 îletişim › Connections 中设置的。',
  'Dosya hazırlanamadı.' => '无法准备该文件。',
  'Flux AI görsel desteği yok.' => 'Flux AI 没有图像支持。',
  'Görsel çevrilemedi.' => '无法渲染图像。',
  'Asistanın görseli gönderilemedi: ' => '助理图片无法发送:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => '您好{first_name},我们已创建您的捐款记录:{donation},总计{amount}。{bank}付款后,您可以将收据发送至此处。谢谢。',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => '您好{first_name},您的捐款已记录:{donation},总计{amount}。' . chr(10) . '' . chr(10) . '感谢您的支持。',
  'Bu senaryoyu oynatacak eklenti kapalı.' => '运行此场景的插件处于非活动状态。',
  'Bu kullanıcının personel araçları yetkisi yok.' => '该用户无权使用员工工具。',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$s将此聊天链接到工作人员%2$s',
