  'Sohbet personele bağlandı' => '与工作人员关联的聊天',
  'Personel bağlantısı kaldırıldı' => '员工链接已删除',
  '— Personel değil —' => '— 不是工作人员 —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp 隐藏了此人的号码,因此助理无法通过号码识别工作人员。如果此人在您的团队中,请在此处链接他们,助理将打开员工工具。',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => '助理通过员工 Flux 角色档案中的号码来识别员工。如果号码不匹配,您可以在此处链接;在与已知号码聊天时,号码排在第一位。',
  'Bu kanal şu an kullanılamıyor.' => '该频道目前不可用。',
  'Site sohbeti' => '现场聊天',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => '来自 WhatsApp、网站聊天和其他渠道的所有消息都会实时显示在这里。选择左侧的聊天。',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'WhatsApp(Evolution API)呼叫中心:查看实时传入和传出消息、开始新聊天、预设回复、标签、作业、内部注释、自动回复;通过聊天注册捐赠(Flux Donate)和证书(Flux Certificates),收据匹配。 OpenRouter 的人工智能响应建议和自动捐赠助手。',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'WhatsApp(Evolution API)呼叫中心:查看实时传入和传出消息、开始新聊天、预设回复、标签、作业、内部注释、自动回复;通过聊天注册捐赠(Flux Donate)和证书(Flux Certificates),收据匹配。 OpenRouter 的人工智能响应建议和自动捐赠助手。',
  'Hide' => '隐藏',
  'Show' => '显示',
  'Deleted for everyone' => '已对所有人删除',
  'Hidden in the panel' => '已在面板中隐藏',
  'Delete for everyone' => '对所有人删除',
  'Hide in the panel only' => '仅在面板中隐藏',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'WhatsApp 不允许对所有人删除收到的消息；消息仍保留在联系人手机上，仅在面板中隐藏。',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => '设置中已关闭“对所有人删除”；消息仅在面板中隐藏，仍保留在联系人手机上。',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => '此渠道不支持“对所有人删除”；消息仅在面板中隐藏，仍保留在联系人手机上。',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => '已超过“对所有人删除”的时限（WhatsApp 允许在发送后约 {h} 小时内删除）。消息仍保留在联系人手机上，仅在面板中隐藏。',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => '只有发送者或管理员可以对所有人删除此消息；您可以在面板中隐藏它。',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => '若对所有人删除，联系人手机上的消息也会变为“此消息已删除”。剩余时间：约 {n} 小时。',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => '已删除的消息保留在服务器上：聊天中显示“此消息已删除”，团队点击即可查看内容。AI 不会读取已删除的消息。',
  'Message not found.' => '未找到消息。',
  'This message was already deleted.' => '此消息已被删除。',
  'Only the sender or an administrator can delete this message for everyone.' => '只有发送者或管理员可以对所有人删除此消息。',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => '此渠道无法对所有人删除此消息。您可以改为在面板中隐藏。',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => '已超过“对所有人删除”的时限。您可以改为在面板中隐藏。',
  'WhatsApp did not delete the message.' => 'WhatsApp 未删除该消息。',
  'Delete for everyone time limit (hours)' => '“对所有人删除”时限（小时）',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'WhatsApp 仅允许在约 2 天 12 小时（60 小时）内对所有人删除已发送的消息。超过时限或对于收到的消息，消息仅在面板中隐藏，仍保留在联系人手机上。设为 0 将关闭“对所有人删除”。已删除的消息永远不会从服务器移除，团队仍可打开查看。',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => '最后更新请求 %1$s。面板打开时，每隔 %2$d 秒检查新消息（回复传输中为 3 秒，没有变化时最多 15 秒），后台标签页则每分钟一次。',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => '打开的标签页按此间隔检查新消息（建议 10），回复传输中每 3 秒一次，没有变化时最多 15 秒。后台标签页每分钟检查一次。出错后退避时间最长到 60 秒。',
  'Flux Donate is not active.' => 'Flux Donate 未启用。',
  'Donor\'s earlier referral' => '捐赠者之前的推荐人',
  'Referral' => '推荐人',
  'Order' => '订单',
  'Confirmation code' => '确认码',
  'Recorded from' => '记录来源',
  'Entered by' => '录入人',
  'Items' => '明细',
  'On behalf of: {n}' => '代表：{n}',
  'Receipts' => '凭证',
  'Revoked' => '已撤销',
  '{n} paid gifts · {m}' => '已付款 {n} 笔 · {m}',
  'No contact details.' => '没有联系方式。',
  'No referral.' => '无推荐人。',
  'Has the payment reached the account? When you confirm, the certificate is made and sent to the donor.' => '款项已到账了吗？确认后将生成证书并发送给捐赠者。',

  'Change history' => '更改记录',
  'Assistant memory' => '助手记忆',
  'Note updated' => '备注已更新',
  'Show less' => '收起',
  'Show all ({n})' => '显示全部 ({n})',
  'Filled from donation and certificate records (one-off update)' => '已根据捐赠和证书记录填写（一次性更新）',
  'Name given by the sending record' => '发送记录中提供的姓名',
  'Filled from donation and certificate records' => '已根据捐赠和证书记录填写',
  'The contact said their name in the chat' => '联系人在聊天中说出了姓名',
  'The contact corrected their name in the chat' => '联系人在聊天中更正了姓名',
  'The contact gave their full name in the chat' => '联系人在聊天中提供了全名',
 ),
